# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

# ---
def make_student(last, first):
    return Student("id-" + last, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Ainsley", "Cora")
        ]
        self.assertEqual(
            seating_rows(students, 2),
            ["Row 1: Ainsley, Cora | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_sort_ignores_case_and_uses_first_name_for_ties(self):
        students = [
            make_student("smith", "Zed"),
            make_student("Smith", "Amy"),
            make_student("Adams", "Bob")
        ]
        self.assertEqual(
            seating_rows(students, 3),
            ["Row 1: Adams, Bob | Smith, Amy | smith, Zed"]
        )

    def test_bad_seat_counts(self):
        students = [make_student("Dunmere", "Piet")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(students, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
